// Violates 1NF: repeating groups in a single column
// orders(id, customer, items) where items = 'book,pen,paper'

// 1NF: atomic values, no repeating groups
// orders(id, customer_id)
// order_items(order_id, item_id, quantity)

// Violates 2NF: partial dependency on composite key
// order_items(order_id, item_id, item_name, quantity)
// item_name depends only on item_id, not the full composite key

// 2NF: remove partial dependencies
// order_items(order_id, item_id, quantity)  -- depends on full key
// items(item_id, item_name, price)          -- item_name moved here

// Violates 3NF: transitive dependency
// employees(emp_id, dept_id, dept_name)
// dept_name depends on dept_id, not directly on emp_id

// 3NF: remove transitive dependencies
// employees(emp_id, dept_id)
// departments(dept_id, dept_name)

// BCNF: every determinant must be a candidate key
// teaching(student, subject, teacher)
// If teacher -> subject (a teacher teaches only one subject),
// teacher is a determinant but not a candidate key -- violates BCNF
// Solution: teacher(teacher, subject) + enrollment(student, teacher)

The choice is not ideology — it is data model, access patterns, and consistency needs. This side-by-side shows the same "save an order" operation in each style.

```sql
-- SQL (PostgreSQL): normalized schema, relational integrity, SQL ad-hoc queries
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL);
CREATE TABLE orders (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  total NUMERIC(10,2) NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

BEGIN;
  INSERT INTO orders (user_id, total) VALUES (42, 99.90);
  UPDATE inventory SET qty = qty - 1 WHERE sku = 'ABC';
COMMIT;   -- ACID: both rows or neither

-- Ad-hoc reporting is trivial
SELECT u.email, SUM(o.total)
FROM users u JOIN orders o ON o.user_id = u.id
WHERE o.created_at > NOW() - INTERVAL '7 days'
GROUP BY u.email ORDER BY 2 DESC LIMIT 10;
```

```javascript
// NoSQL (MongoDB): denormalized document, flexible schema, horizontal scale
db.orders.insertOne({
  _id: ObjectId(),
  user: { id: 42, email: "alice@example.com" },   // embedded copy — read-optimized
  items: [
    { sku: "ABC", qty: 1, price: 99.90 },
    { sku: "XYZ", qty: 2, price: 15.00 }
  ],
  total: 129.90,
  createdAt: new Date()
});

// Single-document reads/writes are atomic; multi-document txns exist but cost more
db.orders.find({ "user.id": 42 })
  .sort({ createdAt: -1 }).limit(10);
```

| Aspect | SQL (Postgres/MySQL) | NoSQL (Mongo/Dynamo) |
| --- | --- | --- |
| Schema | rigid, migrations | flexible, per-doc |
| Transactions | full ACID across tables | single doc ACID; multi-doc ok but slower |
| Joins | cheap (the engine's job) | usually denormalize instead |
| Scale | vertical + read replicas; sharding is work | built-in sharding, horizontal by default |
| Ad-hoc queries | SQL is unbeatable | aggregation pipelines, less flexible |
| Best fit | financial, reporting, complex relations | catalogs, events, user-generated content, high write throughput |

- Reach for **SQL** when data has stable structure, multi-row transactions matter, and the business will ask unpredictable reporting questions.
- Reach for **NoSQL** when the access pattern is known and narrow, writes dominate reads, documents vary in shape, or you need geographic/horizontal scale without operational pain.
- **Polyglot persistence** is the honest answer for most platforms: Postgres for orders, Mongo for catalog, Redis for session, Elasticsearch for search — each doing what it is best at.

-- Simple junction table (composite primary key)
CREATE TABLE student_courses (
    student_id BIGINT REFERENCES students(id),
    course_id  BIGINT REFERENCES courses(id),
    PRIMARY KEY (student_id, course_id)
);

-- Rich junction table with its own attributes and surrogate PK
CREATE TABLE enrollments (
    id          BIGSERIAL PRIMARY KEY,
    student_id  BIGINT NOT NULL REFERENCES students(id),
    course_id   BIGINT NOT NULL REFERENCES courses(id),
    enrolled_at TIMESTAMP NOT NULL DEFAULT now(),
    grade       CHAR(2),
    UNIQUE (student_id, course_id)
);

// JPA: simple @ManyToMany mapping
@Entity
public class Student {
    @Id @GeneratedValue private Long id;
    private String name;

    @ManyToMany
    @JoinTable(
        name = "student_courses",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}

// JPA: rich junction as a dedicated @Entity (preferred when attributes exist)
@Entity
public class Enrollment {
    @Id @GeneratedValue private Long id;

    @ManyToOne
    @JoinColumn(name = "student_id")
    private Student student;

    @ManyToOne
    @JoinColumn(name = "course_id")
    private Course course;

    private LocalDateTime enrolledAt;
    private String grade;
}
